import json

input_vals = [3, 3, 4, 4, 5, 4, 4, 1, 1]

# Fix pairs pattern for 3x18
output_pairs = []
for r in range(3):
    row = []
    for c in range(9):
        val = input_vals[c]
        if r == 0:
            row.extend([val, val])  # (val, val)
        elif r == 1:
            row.extend([val, input_vals[(c + 1) % 9]])  # (val, next)
        else:
            row.extend([val, input_vals[(c + 2) % 9]])  # (val, next_next)
    output_pairs.append(row)

print(f"3x18 pairs fixed:")
for r in range(3):
    print(f"  {output_pairs[r]}")

print(f"\nSubmitting:")
print(json.dumps({"action": "submit", "grid": output_pairs}))

